<script setup lang="ts">
import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus'
import {useRouter} from 'vue-router';import {api,errorMessage} from '../api/http'
const router=useRouter();const recent=ref<any[]>([]);const historyLoading=ref(false);async function fetchRecent(){historyLoading.value=true;try{recent.value=await api<any[]>('/records/documents')}catch(e){ElMessage.error(errorMessage(e))}finally{historyLoading.value=false}}onMounted(fetchRecent)
const csv=ref<File|null>(null),pdf=ref<File|null>(null),owner=ref('export'),ownerId=ref(''),type=ref('INVOICE'),busy=ref(false),result=ref('')
function fileChanged(e:Event,target:'csv'|'pdf'){const f=(e.target as HTMLInputElement).files?.[0]||null;if(target==='csv')csv.value=f;else pdf.value=f}
async function sendCsv(){if(!csv.value)return ElMessage.warning('CSVを選択してください');busy.value=true;try{const form=new FormData();form.append('file',csv.value);const data=await api<any>('/imports/csv',{method:'POST',body:form});result.value=JSON.stringify(data,null,2);ElMessage.success('取込み完了')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function sendPdf(){if(!pdf.value||!Number(ownerId.value))return ElMessage.warning('PDFと関連レコードIDを入力してください');busy.value=true;try{const form=new FormData();form.append('file',pdf.value);form.append('type',type.value);form.append(owner.value==='export'?'exportId':'orderId',ownerId.value);const data=await api<any>('/documents',{method:'POST',body:form});result.value=JSON.stringify(data,null,2);ElMessage.success('PDFアップロード完了');await fetchRecent()}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
</script>
<template><h1 class="page-title">データ取込み</h1><div class="banner">初版は管理者のみアップロードできます。CSVは限定した列構成（1輸出につき1設備）を対象とします。画像・スキャンPDFの自動文字認識は対象外です。</div><section class="panel"><header class="panel-heading">CSVデータ取込み</header><div class="panel-body"><p>標準テンプレート: <a href="/samples/export-import-template.csv" download>export-import-template.csv</a></p><input type="file" accept=".csv,text/csv" @change="fileChanged($event,'csv')"/><div style="margin-top:15px"><el-button type="primary" :loading="busy" @click="sendCsv">CSVを取込む</el-button></div><p class="data-note">ヘッダと日付はテンプレートに従ってください。新規レコードは DRAFT 登録されるため、元資料を照合してください。</p></div></section><section class="panel"><header class="panel-heading">原票PDFのアップロード</header><div class="panel-body"><el-form label-position="top"><el-row :gutter="18"><el-col :span="6"><el-form-item label="関連先"><el-select v-model="owner" style="width:100%"><el-option label="輸出レコード" value="export"/><el-option label="販売レコード" value="order"/></el-select></el-form-item></el-col><el-col :span="6"><el-form-item label="関連ID（内部ID）"><el-input v-model="ownerId" placeholder="1"/></el-form-item></el-col><el-col :span="6"><el-form-item label="書類種別"><el-select v-model="type" style="width:100%"><el-option v-for="t in ['INVOICE','PACKING_LIST','ORDER','CONTRACT','OTHER']" :key="t" :label="t" :value="t"/></el-select></el-form-item></el-col></el-row><input type="file" accept="application/pdf,.pdf" @change="fileChanged($event,'pdf')"/><div style="margin-top:15px"><el-button type="primary" :loading="busy" @click="sendPdf">PDFを登録</el-button></div></el-form><p class="data-note">ファイルは15MB以下のPDFのみ。元ファイルを変更せずにプレビューできます。</p></div></section><section v-if="result" class="panel"><header class="panel-heading">取込み結果</header><div class="panel-body"><pre>{{result}}</pre></div></section><section class="panel"><header class="panel-heading">登録済み書類（最新80件）</header><div class="panel-body"><el-table :data="recent" v-loading="historyLoading" stripe border><el-table-column prop="file_name" label="ファイル名" min-width="220" show-overflow-tooltip/><el-table-column prop="document_type" label="種別" width="125"/><el-table-column prop="created_at" label="登録日時" min-width="155"/><el-table-column label="関連レコード" width="135"><template #default="s"><el-button size="small" @click="router.push(s.row.export_id?'/exports/'+s.row.export_id+'/documents':'/sales/'+s.row.order_id+'/documents')">原票を見る</el-button></template></el-table-column></el-table><p class="data-note">SYN26 書類はテスト用に生成した PDF です。実際の取込み監査ログとは異なります。</p></div></section></template>
